23.latex:
\textbf{Integer Programming} \\
\underline{\text{[MEJ] P. 148}} \quad \text{Machine Scheduling} \\
M = \{1, 2, \dots, m\} \quad m - \text{Machines} \\
J = \{1, 2, \dots, n\} \quad n - \text{Jobs} \\
d_{ij} = \text{running time of job } j \text{ in machine } i \\
\boxed{
\begin{aligned}
\min \quad & t \quad (\text{total run time}) \\
\text{s.t. } \quad & \sum_{i \in M} x_{ij} = 1 \quad j \in J \\
& \sum_{j \in J} d_{ij} x_{ij} \le t \\
& x_{ij} \in \{0, 1\}
\end{aligned}
}

